def truncate_number(number: float) -> float:
    """
    Given a positive floating point number, returns the decimal part of the number.

    :param number: The floating point number to truncate.
    :return: The decimal part of the number.
    """
    if number < 0:
        raise ValueError("The number must be positive.")

    return number - int(number)

def find_topmost_carpet(n, carpets, point) -> int:
    x, y = point
    topmost_carpet = -1
    for i in range(n):
        a, b, g, k = carpets[i]
        if a <= x <= a + g and b <= y <= b + k:
            topmost_carpet = i + 1
    return topmost_carpet

