def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    grid = [[0] * N for _ in range(N)]

    for x, y, value in grid_values:
        if x == 0 and y == 0 and value == 0:
            break
        if 0 <= x < N and 0 <= y < N:
            grid[x][y] = value

    dp = [[[float('-inf')] * 4] * N for _ in range(N)]
    dp[0][0][0] = grid[0][0]

    for i in range(N):
        for j in range(N):
            if i == 0 and j == 0:
                continue
            for k in range(4):
                if i > 0:
                    dp[i][j][k] = max(dp[i][j][k], dp[i-1][j][k] + grid[i][j], dp[i-1][j][k-1] + grid[i][j])
                if j > 0:
                    dp[i][j][k] = max(dp[i][j][k], dp[i][j-1][k] + grid[i][j], dp[i][j-1][k-1] + grid[i][j])
                if i > 0 and j > 0:
                    dp[i][j][k] = max(dp[i][j][k], dp[i-1][j-1][k] + grid[i][j], dp[i-1][j-1][k-1] + grid[i][j])

    return max(max(max(dp[N-1][N-1])) for _ in range(4))

def max_product(num_str: str, N: int, K: int) -> int:
    """Calculate the maximum product by inserting K multiplication signs into the number string."""

    if N - 1 == K:
        return int(num_str)
    if K == 0:
        return int(num_str)

    max_product = 0
    for i in range(1, N - K):
        left_part = num_str[:i]
        right_part = num_str[i:]
        current_product = int(left_part) * int(right_part)
        remaining_product = max_product(right_part[K-i+1:], K-i-1) if K-i-1 >= 0 else 1
        max_product = max(max_product, current_product * remaining_product)

    return max_product

