def max_energy(beads):
    n = len(beads)
    dp = [[[-float('inf')] * 2 for _ in range(n)] for _ in range(n)]

    # Initialize dp for single beads
    for j in range(n):
        dp[j][j][0] = dp[j][j][1] = beads[j]

    for gap in range(1, n):
        for i in range(n):
            j = (i + gap) % n
            for lastmerged in range(2):
                if gap == 1:
                    dp[i][j][lastmerged] = max(beads[i] * beads[i] * beads[j], beads[j] * beads[j] * beads[i])
                else:
                    if lastmerged == 0:
                        dp[i][j][0] = max(dp[i][k][0] + dp[k + 1][j][1] * beads[k] * beads[j] for k in range(i, j))
                        dp[i][j][1] = dp[i][j][0] if beads[j] == beads[i] else 0
                    else:
                        dp[i][j][1] = max(dp[k][j][1] + dp[i][k][0] * beads[k] * beads[i] for k in range(i, j))
                        dp[i][j][0] = dp[i][j][1] if beads[i] == beads[j] else 0

    return max(dp[i][i][1] for i in range(n))

