def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    """
    Converts a list of polynomial coefficients into a formatted string representation.

    :param n: The highest degree of the polynomial.
    :param coeffs: A list of coefficients, starting with the coefficient of the highest degree term.
    :return: The string representation of the polynomial.
    """
    terms = []
    for i in range(n, -1, -1):
        coeff = coeffs[n - i]
        if coeff == 0:
            continue

        if i == 0:
            term = f"{abs(coeff)}"
        elif i == 1:
            if coeff == 1:
                term = "x"
            elif coeff == -1:
                term = "-x"
            else:
                term = f"{abs(coeff)}x"
        else:
            if coeff == 1:
                term = f"x^{i}"
            elif coeff == -1:
                term = f"-x^{i}"
            else:
                term = f"{abs(coeff)}x^{i}"

        terms.append(term)

    result = terms[0] if terms else "0"
    for term in terms[1:]:
        if term.startswith("-"):
            result += term
        else:
            result += "+" + term

    return result

def decode(encoded: str, original: str, message: str) -> str:
    """
    Decodes an encrypted message using a cipher derived from a known encoded-original pair.

    :param encoded: The encoded string.
    :param original: The original string.
    :param message: The encrypted message to be decoded.
    :return: The decoded message if successful, or "Failed" if the decoding is not possible.
    """
    if len(encoded) != len(original):
        return "Failed"

    mapping = {}
    for enc_char, orig_char in zip(encoded, original):
        if enc_char in mapping and mapping[enc_char] != orig_char:
            return "Failed"
        mapping[enc_char] = orig_char

    decoded = []
    for char in message:
        if char in mapping:
            decoded.append(mapping[char])
        else:
            return "Failed"

    return ''.join(decoded)

def count_coprime_pairs(x0: int, y0: int) -> int:
    """
    Counts the number of pairs of positive integers (P, Q) such that P and Q have x0 as their greatest common divisor (GCD)
    and y0 as their least common multiple (LCM).

    Args:
    x0 (int): The GCD that each pair (P, Q) must have.
    y0 (int): The LCM that each pair (P, Q) must have.

    Returns:
    int: The count of all possible pairs (P, Q) that meet the specified criteria.
    """
    if x0 > y0:
        return 0

    count = 0
    q = y0 // x0
    for a in range(1, q + 1):
        if q % a == 0:
            b = q // a
            if a == b:
                count += 1
            elif gcd(a, b) == 1:
                count += 2
    return count

def gcd(a: int, b: int) -> int:
    while b:
        a, b = b, a % b
    return a

def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    """
    Evaluates the consistency of a scenario where one participant is the criminal based on the given statements.

    Parameters:
    - scenario (str): The name of the participant being tested as the potential criminal.
    - liar_count (set): A set of names of participants who are assumed to be liars.
    - statements (dict): A dictionary mapping participant names to lists of their respective statements.
    - days_of_week (set): A set of strings representing the days of the week.

    Returns:
    - bool: True if the scenario is consistent with the statements, False otherwise.
    """
    def is_criminal_statement(statement: str) -> bool:
        return "I am guilty" in statement

    for participant, participant_statements in statements.items():
        for statement in participant_statements:
            if participant in liar_count:
                if is_criminal_statement(statement):
                    if participant != scenario:
                        return False
                else:
                    if participant == scenario:
                        return False
            else:
                if is_criminal_statement(statement):
                    if participant == scenario:
                        return False
                else:
                    if participant != scenario:
                        return False

    return True

def calculate_arrangements(n: int, m: int, a: list[int]) -> int:
    MOD = 10**6 + 7

    dp = [[0] * (m + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    for i in range(1, n + 1):
        for j in range(1, m + 1):
            for k in range(min(j, a[i - 1]) + 1):
                dp[i][j] += dp[i - 1][j - k]
                dp[i][j] %= MOD

    return sum(dp[n]) % MOD

def minimum_students_to_leave(heights):
    n = len(heights)
    if n <= 2:
        return 0

    max_height = max(heights)
    max_index = heights.index(max_height)

    left = 0
    while max_index - left >= 1 and heights[max_index - left] == heights[max_index - left - 1]:
        left += 1

    right = 0
    while max_index + right + 1 < n and heights[max_index + right] == heights[max_index + right + 1]:
        right += 1

    return n - (1 + left + right)
